data "cloudinit_config" "web" {
  gzip          = true
  base64_encode = true
  part {
    content_type = "text/cloud-config"
    content      = file("cloud-config.yaml")
  }
  part {
    content_type = "text/x-shellscript"
    content      = file("register.sh")
  }
}
resource "aws_instance" "web" { user_data_base64 = data.cloudinit_config.web.rendered }
